// High School course unit (docs/design/COURSES.md, docs/design/COURSE_QUALITY.md): AP Human Geography, Unit 3, Cultural Patterns and Processes
// (the course's public outline, topics 3.1-3.8; our own wording and questions, nothing copied). Taught: culture, traits,
// complexes and regions; folk and popular culture; the cultural landscape (Sauer), sequent occupancy and toponyms;
// formal, functional and vernacular regions; relocation and expansion diffusion (contagious, hierarchical, stimulus), hearths and
// distance decay; the historical causes of diffusion (trade routes such as the Silk Road, the Columbian Exchange, colonialism,
// forced migration, missionaries, steamships and the telegraph); contemporary causes (globalization, time-space compression,
// the internet and air travel, transnational corporations, the digital divide); universalizing and ethnic religions with their
// hearths and branches; language families, branches, dialects, isolates, lingua francas, pidgins and creoles; and the effects
// of diffusion (acculturation, assimilation, syncretism, multiculturalism, convergence and divergence, glocalization, language loss).
// Every invented example, country and number is labelled fictional and chosen so each answer is whole or terminates; the factual
// questions are standard textbook statements, hedged where scholars disagree. Nothing here ranks a culture or a religion.
const tab=(title,rows,cols=['Value'])=>({t:'setups',title,head:'',rows,cols});
/* Lesson figures use 640 × 280 screen positions, converted to the figure renderer's upward y axis.
   Labels stay inside the 44..596 × 56..248 drawing window; shapes reveal in order. */
const scene=(title,draw)=>{const pts={},polys=[],segs=[],circles=[],notes=[];let i=0;const point=(x,y)=>{const k='P'+i++;pts[k]=[x,280-y];return k;};
 const pen={box:(x,y,w,h,col=0)=>{const v=[[x,y],[x+w,y],[x+w,y+h],[x,y+h]].map(([a,b])=>point(a,b)).join('');polys.push({v,col});},line:(x,y,u,v,col=0,arrows=0,dash=false,w=2)=>segs.push({v:point(x,y)+point(u,v),col,arrows,dash,w}),circle:(x,y,r,col=0)=>circles.push({c:point(x,y),r,col}),note:(x,y,text,col=0)=>notes.push({at:[x,280-y],text,col})};
 draw(pen);return {t:'figure',title,view:[44,596,32,224],pts,hide:Object.keys(pts).join(''),dots:'',polys,segs,circles,notes};};
const board=(title,lines)=>({t:'board',title,lines,box:true});
const n=v=>v.toLocaleString('en-US');
const pct=v=>String(Math.round(v*1e6)/1e6);
/* The Try-it questions in pool form; the generator skips them. */
const TRY=['Saying a short blessing after someone sneezes. Is this a cultural trait or a cultural complex?',
 'A fictional town\'s slang word spreads from neighbor to neighbor until nearly everyone nearby uses it. Is this contagious, hierarchical or stimulus diffusion?',
 'A fictional caravan travels 25 kilometers a day along a trade route that is 900 kilometers long. How many days does the trip take?',
 'A fictional family keeps its language and holidays at home but also learns the local language and joins local school events. Which term fits best: acculturation, assimilation or syncretism?'];
/* lettered choices, the right one moved to position k */
const choose=(right,wrong,k)=>{const o=[...wrong];o.splice(k%3,0,right);return {text:o.map((x,i)=>`${'ABC'[i]}: ${x}`).join(', '),letter:'ABC'[o.indexOf(right)]};};
const tryIt=s=>`Try it: ${s[0].toLowerCase()+s.slice(1)}`;
/* sorted cases: [text, answer] */
const TRAIT=[
 ['Using a particular greeting, such as a handshake.','trait'],
 ['A fictional Valley Festival with its special foods, dances, costumes and songs.','complex'],
 ['Eating one kind of flatbread at breakfast.','trait'],
 ['Ranching, with its horses, saddles, cattle drives, rodeos and work clothing.','complex'],
 ['Wearing a ring at a wedding.','trait'],
 ['Surfing, with its boards, beaches, slang, music and clothing.','complex']];
const MATERIAL=[
 ['A hand-woven blanket','material culture','nonmaterial culture'],
 ['A belief that guests should be welcomed warmly','nonmaterial culture','material culture'],
 ['A wooden fishing boat','material culture','nonmaterial culture'],
 ['The grammar and vocabulary of a language','nonmaterial culture','material culture']];
const SCAPE=[
 ['A highway cutting through farmland.','cultural'],
 ['A mountain range.','physical'],
 ['Rice terraces cut into a hillside.','cultural'],
 ['A river delta formed by sediment.','physical'],
 ['A church spire or a mosque dome over a town.','cultural']];
const REGION=[
 ['An area where nearly everyone speaks the same language.','formal'],
 ['The area served by one city\'s bus and rail lines, all centered on its downtown station.','functional'],
 ['A part of a country that people call "the Heartland", with no official borders.','vernacular'],
 ['A country, defined by its borders and laws.','formal'],
 ['The area that receives one radio station\'s broadcast from a single tower.','functional'],
 ['A fictional neighborhood that locals call "Little River", though no official map shows it.','vernacular']];
const RELOC=[
 ['Immigrants bring their family recipes to a new country and open restaurants.','relocation'],
 ['A rumor spreads through a town as neighbors tell neighbors.','expansion'],
 ['Settlers move to a new colony and bring their language with them.','relocation'],
 ['A video spreads from person to person online while its creator stays where she is.','expansion'],
 ['A refugee community carries its music and food to a new country.','relocation']];
const KIND=[
 ['A joke spreads from neighbor to neighbor across a fictional village until nearly everyone has heard it.','contagious'],
 ['A fashion first worn in a few world-famous cities reaches mid-sized cities and then small towns.','hierarchical'],
 ['In the 1820s Sequoyah created a writing system for the Cherokee language after learning that other peoples used writing. The idea spread, but the system itself was new.','stimulus'],
 ['A fictional rash of enthusiasm for a game starts in one neighborhood and passes to the nearest neighbors first.','contagious'],
 ['A new style of dress is first adopted by a fictional kingdom\'s rulers and then copied by officials and ordinary people.','hierarchical']];
const FAITH=[
 ['Christianity','universalizing'],['Judaism','ethnic'],['Buddhism','universalizing'],['Shinto','ethnic'],['Hinduism','ethnic'],['Islam','universalizing']];
const EFFECT=[
 ['A fictional family moves abroad, learns the new language and celebrates local holidays, while still cooking its home recipes and speaking its own language at home.','acculturation'],
 ['By the third generation, a fictional immigrant family speaks only the dominant language, has dropped its earlier customs and is no longer seen as distinct.','assimilation'],
 ['In a fictional town, a harvest festival combines an older local ritual with a religious holiday brought by newcomers into one celebration.','syncretism'],
 ['A fictional city supports schools, festivals and media in six languages, and each community keeps its identity.','multiculturalism'],
 ['A student joins a new school and adopts its sports and slang but keeps speaking her family\'s language at home.','acculturation'],
 ['Two traditions in a fictional region merge their beliefs into one new faith.','syncretism']];
export default {
id:'geography-h-ap-hug-cultural-patterns-and-processes',subject:'geography',level:5,grade:9,standard:'AP Human Geography, Unit 3',
title:'Cultural patterns and processes',
goal:'Explain culture, traits and complexes, read cultural landscapes and regions, sort relocation, contagious, hierarchical and stimulus diffusion, explain the historical and contemporary causes of diffusion including time-space compression, tell universalizing from ethnic religions and read language families, and weigh acculturation, assimilation, syncretism, multiculturalism, convergence and divergence.',
points:20,
skills:{culture:'Introduction to culture',landscape:'Cultural landscapes',patterns:'Cultural patterns',diffusion:'Types of diffusion',historical:'Historical causes of diffusion',contemporary:'Contemporary causes of diffusion',religion:'Diffusion of religion',language:'Diffusion of language',effects:'Effects of diffusion'},
outline:[['3.1','Introduction to culture',['culture']],['3.2','Cultural landscapes',['landscape']],['3.3','Cultural patterns',['patterns']],['3.4','Types of diffusion',['diffusion']],['3.5','Historical causes of diffusion',['historical']],['3.6','Contemporary causes of diffusion',['contemporary']],['3.7','Diffusion of religion and language',['religion','language']],['3.8','Effects of diffusion',['effects']]],
steps:[
 {skill:"culture",say:"Culture is the shared beliefs, practices, language and material things of a group, learned and passed on rather than inherited biologically. Geographers study it in pieces. A cultural trait is a single element, such as a greeting. A culture complex is a set of related traits that go together, such as the foods, dances and costumes of a festival. Where a complex is shared, we can map a cultural region.",pic:scene('From trait to complex to region (fictional example)',d=>{for(const [x,t1,t2,e,col] of [[62,'Trait','one element','a greeting',0],[250,'Complex','related traits','a harvest festival',1],[438,'Region','shared complex','the valley that keeps it',2]]){d.box(x,98,140,64,col);d.note(x+70,121,t1,col);d.note(x+70,144,t2,col);d.note(x+70,194,e,3);}d.line(206,130,244,130,3,1);d.line(394,130,432,130,3,1);d.note(320,232,'Traits combine into complexes; complexes can be mapped');}),
  check:{prompt:tryIt(TRY[0]),answer:'trait',options:['trait','complex','landscape'],hint:'It is one small element, not a set of related traits.',pic:tab('The case',[['custom','a short blessing after a sneeze']])}},
 {skill:"culture",say:"Culture has material and nonmaterial parts. Material culture is the things people make and use, such as tools, clothing and buildings. Nonmaterial culture is ideas and shared understandings: beliefs, values, norms (expected behavior), language and customs. Geographers also warn against ethnocentrism, judging other cultures by your own standards, and favor cultural relativism, understanding a culture on its own terms.",pic:board('Parts of culture',['Material: things people make and use','Nonmaterial: beliefs, values, norms, language','Norm: a shared expectation of behavior','Ethnocentrism: judging by your own standards','Cultural relativism: understanding on its own terms'])},
 {skill:"landscape",say:"The cultural landscape is the visible imprint of human activity on the land: buildings, fields, roads, signs and monuments. Carl Sauer made the idea central to geography. Sequent occupancy, a term associated with Derwent Whittlesey, describes how successive groups each leave marks on the same place. In this fictional site, farm fields became a market hall and later apartments with shops, and traces of each layer can remain.",pic:scene('Sequent occupancy: one fictional site',d=>{d.box(130,170,290,40,2);d.note(275,190,'Layer 1: farm fields',2);d.box(130,120,290,40,1);d.note(275,140,'Layer 2: market hall',1);d.box(130,70,290,40,0);d.note(275,90,'Layer 3: apartments and shops',0);d.line(480,205,480,78,3,1);d.note(480,222,'earlier',3);d.note(480,60,'later',3);d.note(275,232,'Each group leaves marks on the same place');})},
 {skill:"landscape",say:"Landscapes carry clues about who lives or lived somewhere. Houses of worship show religion; signs in several languages suggest which groups live in or visit an area; building styles can reflect local materials and climate. Place names, called toponyms, often record languages, people or events. Ethnic neighborhoods, where people of a shared heritage have clustered, often keep distinctive shops, food and religious buildings. These are clues, not proof about any one person.",pic:scene('A fictional town map: reading the landscape',d=>{for(const y of [90,130,170,210])d.line(80,y,560,y,3,0,false,1);for(const x of [140,240,340,440,540])d.line(x,80,x,220,3,0,false,1);d.box(240,130,200,80,2);d.note(340,170,'Ethnic neighborhood',2);d.note(340,188,'signs in two languages',2);d.circle(140,110,10,1);d.note(140,148,'church spire',1);d.note(490,108,'Mill Street',0);d.note(490,124,'(a toponym)',0);d.note(160,232,'Streets and buildings are cultural landscape',3);})},
 {skill:"patterns",say:"Cultural regions come in three kinds. A formal region has a shared trait across the area, such as one language. A functional region is organized around a central node and linked by flows, such as a transit network or a broadcast area. A vernacular, or perceptual, region exists in people's minds, like 'the Heartland' with no official border. Boundaries of any region are usually blurry.",pic:scene('Three kinds of region (fictional)',d=>{d.box(60,90,150,110,0);d.note(135,145,'Formal',0);d.note(135,166,'shared trait');d.circle(350,145,14,1);for(const [x,y] of [[290,100],[410,100],[290,190],[410,190]]){d.circle(x,y,8,1);d.line(350,145,x,y,1,0,false,1);}d.note(350,224,'Functional: linked to a node',1);for(const [a,b,c,e] of [[470,90,580,90],[580,90,580,200],[580,200,470,200],[470,200,470,90]])d.line(a,b,c,e,2,0,true,2);d.note(525,145,'Vernacular',2);d.note(525,166,'a felt region');d.note(135,224,'Formal: same trait',0);d.note(525,224,'Perceived',2);})},
 {skill:"patterns",say:"Folk culture is traditional practice shared by a small, fairly uniform group, often rural and passed on locally by example. Popular culture is shared by a large, varied group, spreads widely through media and trade, and changes quickly. Cultural patterns also vary with age, gender, ethnicity and religion, and gender roles differ across societies and change over time. Many places show neolocalism, renewed attention to local identity as a reaction to globalization.",pic:board('Folk and popular culture',['Folk: small group, often rural, passed on locally','Popular: large varied group, spreads widely, changes fast','Folk example: a village dance taught by elders','Popular example: a music style streamed worldwide','The two overlap; the line is not sharp'])},
 {skill:"diffusion",say:"Diffusion is the spread of a trait, idea or innovation from its hearth, the place where it began. In relocation diffusion, people carry the trait to a new place, as migrants do with a language or a recipe. In expansion diffusion, the trait spreads among people while staying strong in its hearth. The contagious type spreads outward person to person, like a ripple, reaching nearly everyone near the hearth first.",eq:"relocation: people move  |  expansion: the idea spreads",pic:scene('Relocation and contagious diffusion (schematic)',d=>{d.note(150,80,'Relocation',0);d.circle(80,150,16,0);d.circle(250,150,12,0);d.line(100,150,230,150,0,1,true,3);d.note(80,190,'hearth');d.note(250,190,'migrants arrive');d.note(450,80,'Contagious expansion',1);d.circle(450,150,16,1);for(const [x,y] of [[505,150],[395,150],[450,100],[450,200]]){d.circle(x,y,9,1);d.line(450,150,x,y,1,1,false,2);}for(const [x,y] of [[545,150],[355,150],[450,70],[450,230]])d.circle(x,y,6,2);}),
  check:{prompt:tryIt(TRY[1]),answer:'contagious',options:['contagious','hierarchical','stimulus'],hint:'It passes to the nearest people first, like a ripple.',pic:tab('The case',[['trait','a slang word'],['spread','neighbor to neighbor']])}},
 {skill:"diffusion",say:"Two other kinds of expansion diffusion matter. Hierarchical diffusion moves through a ranking, often from large, influential places or people down to smaller ones, as a fashion might go from world cities to towns. Stimulus diffusion spreads an underlying idea but not the exact trait, so the new place adapts it. Sequoyah's Cherokee writing system, created after he learned that other peoples used writing, is a common example.",pic:scene('Hierarchical and stimulus diffusion (schematic)',d=>{d.note(145,70,'Hierarchical',0);d.box(60,84,170,36,0);d.note(145,102,'Large city',0);d.box(60,138,170,36,1);d.note(145,156,'Mid-size city',1);d.box(60,192,170,36,2);d.note(145,210,'Small town',2);d.line(145,122,145,136,3,1);d.line(145,176,145,190,3,1);d.note(450,70,'Stimulus',1);d.box(365,96,170,40,0);d.note(450,116,'The idea spreads',0);d.box(365,176,170,40,1);d.note(450,196,'A new, adapted trait',1);d.line(450,138,450,174,3,1);})},
 {skill:"diffusion",say:"Distance decay says that, other things equal, interaction and adoption usually fall as distance from a hearth grows. Mountains, oceans and cultural taboos act as barriers; roads, rivers, trade routes and media shorten effective distance. This fictional graph shows the share of households adopting a new tool, by distance from the hearth: it is high near the hearth and falls steadily outward.",pic:{t:'plot',title:'Distance decay (fictional data)',x:[0,400],y:[0,100],paths:[{pts:[[0,90],[50,62],[100,44],[150,30],[200,20],[300,9],[400,5]]}],points:[{x:0,y:90,label:'hearth: 90%'},{x:200,y:20,label:'200 km: 20%'}]}},
 {skill:"historical",say:"Long before the internet, diffusion followed trade, conquest, migration and exploration. The Silk Road network carried goods, technologies and religions such as Buddhism across Eurasia over many centuries. After 1492 the Columbian Exchange moved crops, animals, people and diseases between the Eastern and Western Hemispheres. European colonialism spread languages and institutions, often by imposition, and the forced migration of millions of enslaved Africans carried African foodways, music and religions into the Americas.",pic:{t:'timeline',events:['Silk Road trade across Eurasia','Columbian Exchange after 1492','Colonial empires, 1500s to 1900s','Steamships and telegraph, 1800s','Jets and internet, 1900s to now']}},
 {skill:"historical",say:"Historical diffusion was slower, so we can estimate it with simple arithmetic. In this fictional example a caravan travels 30 kilometers a day on a 1,200-kilometer route. Time equals distance divided by speed, giving 40 days. Faster transport, such as steamships and railways in the 1800s, cut times like these and sped up the spread of goods, people and news.",eq:"days = distance ÷ speed",pic:board('Fictional caravan',['Route: 1,200 km, speed 30 km per day','Days = distance ÷ speed','1,200 ÷ 30 = 40 days']),
  check:{prompt:tryIt(TRY[2]),answer:36,options:[36,875,3.6],hint:'Divide 900 kilometers by 25 kilometers a day.',pic:tab('A fictional caravan',[['distance','900 km'],['speed','25 km per day']])}},
 {skill:"contemporary",say:"Today diffusion is driven by globalization, the growing connection of economies, people and cultures. Time-space compression is the shrinking of the effective time it takes to travel or communicate between places, so the world feels smaller. Air travel, container shipping, mobile phones, the internet and mass media move people, goods and ideas fast. Transnational corporations operate in many countries and spread products and brands. The digital divide, unequal access to technology, limits who takes part.",pic:{t:'chart',kind:'bars',title:'Fictional ocean crossing times (days)',bars:[{label:'Sailing ship',value:40},{label:'Steamship',value:10},{label:'Jet plane',value:1}]}},
 {skill:"religion",say:"Universalizing religions actively seek new followers across cultures; the largest are Christianity, Islam and Buddhism, each with branches. Ethnic religions are closely tied to a people or place and generally do not seek converts; Hinduism, Judaism and Shinto are usually classed this way. Christianity and Judaism began in Southwest Asia, Islam on the Arabian Peninsula, and Hinduism and Buddhism have roots in South Asia. Universalizing faiths spread by expansion and relocation; ethnic ones mostly by migration.",pic:scene('Two kinds of religion (usual classification)',d=>{d.box(60,80,230,44,0);d.note(175,102,'Universalizing',0);d.note(175,142,'Christianity, Islam, Buddhism');d.note(175,162,'Catholic, Protestant, Orthodox');d.note(175,180,'Sunni, Shi\'a');d.note(175,198,'Theravada, Mahayana, Vajrayana');d.box(350,80,230,44,1);d.note(465,102,'Ethnic',1);d.note(465,142,'Hinduism, Judaism, Shinto');d.note(465,162,'and many Indigenous traditions');d.note(465,182,'tied to a people or place');d.note(320,232,'Hearths: Southwest Asia and South Asia',3);})},
 {skill:"language",say:"Languages are grouped by shared ancestry. A language family contains branches, branches contain groups, groups contain languages, and languages have dialects. Indo-European is the family with the most speakers, with branches such as Germanic (English, German, Dutch), Romance (Spanish, French, Italian), Balto-Slavic (Russian, Polish) and Indo-Iranian (Hindi, Persian). Linguists compare cognates, similar words in related languages, to reconstruct earlier languages.",pic:scene('One family, four branches',d=>{d.box(220,70,200,36,0);d.note(320,88,'Indo-European family',0);for(const [x,t,a,b,c] of [[50,'Germanic','English','German','Dutch'],[195,'Romance','Spanish','French','Italian'],[340,'Balto-Slavic','Russian','Polish',''],[485,'Indo-Iranian','Hindi','Persian','']]){d.line(320,108,x+55,134,3,1,false,1);d.box(x,136,110,32,1);d.note(x+55,152,t,1);d.note(x+55,186,a);d.note(x+55,204,b);if(c)d.note(x+55,222,c);}})},
 {skill:"language",say:"Other terms describe how languages meet. A lingua franca is a shared language used between people whose first languages differ. A pidgin is a contact language used between groups without a shared first language. A traditional account describes a creole as a pidgin that becomes a community's first language. Scholars debate this origin model; a preceding pidgin stage is not established for every creole. Creoles are natural languages with systematic grammars. An isolate has no known relatives, as Basque is usually classified. An official language is designated by a government. Small languages can become endangered when speakers shift to a dominant language, though some, such as Hebrew, have been revived.",pic:board('Language terms',['Family → branch → group → language → dialect','Lingua franca: shared language between groups','Pidgin: simplified contact language','Traditional account: pidgin → native community language','Isolate: no known relatives, such as Basque'])},
 {skill:"effects",say:"Diffusion changes cultures in several ways. Acculturation is adopting some traits of another culture while keeping your own. Assimilation is adopting the dominant culture so fully that distinctive traits fade. Syncretism blends elements of different cultures or religions into a new form. Multiculturalism is a society where several cultures coexist and each keeps its identity. These are tendencies and people experience them very differently.",pic:scene('Four outcomes of cultural contact',d=>{for(const [x,y,t,e,col] of [[60,82,'Acculturation','adopt some, keep your own',0],[340,82,'Assimilation','adopt the dominant culture',1],[60,166,'Syncretism','blend into something new',2],[340,166,'Multiculturalism','many cultures coexist',3]]){d.box(x,y,230,60,col);d.note(x+115,y+22,t,col);d.note(x+115,y+44,e,col);}}),
  check:{prompt:tryIt(TRY[3]),answer:'acculturation',options:['acculturation','assimilation','syncretism'],hint:'The family adds new traits but keeps its own.',pic:tab('The case',[['at home','keeps language and holidays'],['outside','learns the local language']])}},
 {skill:"effects",summary:true,say:"Tie the unit together by tracing a trait. Begin with its hearth, name how it spread (relocation or a kind of expansion, helped by historical or contemporary causes), and then ask what it did: did cultures converge, diverge, blend or adapt, as glocalization does with global products? Check the cultural landscape and language for evidence. Avoid ranking cultures, and remember that most real traits mix several diffusion types.",pic:scene('Unit 3: tracing a trait',d=>{for(const [x,a,b,col] of [[50,'Hearth','where it began',0],[195,'Diffusion','type and cause',1],[340,'Effects','blend, adapt, resist',2],[485,'Evidence','landscape, language',3]]){d.box(x,104,110,56,col);d.note(x+55,125,a,col);d.note(x+55,146,b,col);}for(const x of [162,307,452])d.line(x,132,x+30,132,3,1);d.note(320,222,'Hearth → diffusion → effect, with evidence on the map');})}],
progression:{requires:['geography-h-ap-hug-population-and-migration'],operations:1,demand:'Sort cultural traits, regions and landscapes, classify diffusion as relocation, contagious, hierarchical or stimulus, work out travel times and percent changes, and match religions, language families and cultural effects to their definitions.'},
items(add){
 const seen=new Set(TRY);
 const put=(skill,prompt,answer,pic,explanation,accept)=>{if(seen.has(prompt))return;seen.add(prompt);add(skill,prompt,answer,pic,explanation,accept);};
 const ask=(skill,rows,pic,k0=0)=>rows.forEach(([q,right,wrong,why],k)=>{const c=choose(right,wrong,k+k0);put(skill,`${q} ${c.text}. Answer A, B or C.`,c.letter,pic,why||`The answer is ${right}.`,[right]);});
 const sort=(skill,rows,ask2,names,pic)=>rows.forEach(([s,k])=>put(skill,`${s} ${ask2}`,k,tab(pic,[['case',s]],['']),names[k]));
 /* culture */
 ask('culture',[['What is culture?','the shared beliefs, practices, language and material things of a group that are learned and passed on',['the physical features of a place such as climate and landforms','the laws a national government passes'],'Culture is what a group learns and passes on: beliefs, customs, language and material things. Climate and landforms are physical, not cultural.'],
  ['What is a cultural trait?','a single element of culture, such as a greeting custom or a food',['a whole region where one language is spoken','a government policy about culture'],'A cultural trait is one single element of culture, such as a way of greeting, a food or a style of dress.'],
  ['What is a culture complex?','a group of related traits that go together',['a single custom on its own','a region with one language'],'A culture complex is a set of related traits that go together, such as all the customs around raising and eating cattle.'],
  ['What is ethnocentrism?','judging other cultures by the standards of your own',['understanding a culture on its own terms','moving to a new country'],'Ethnocentrism is judging other cultures by the standards of your own and often seeing your own as better.'],
  ['What is cultural relativism?','trying to understand a culture on its own terms',['judging all other cultures by your own','the spread of one culture across the world'],'Cultural relativism means trying to understand a culture by its own values and context, rather than judging it by yours.']],tab('Culture',[['trait','one element'],['complex','related traits'],['region','where a complex is shared']],['Means']));
 sort('culture',TRAIT,'Is this a cultural trait or a cultural complex?',{trait:'It is one element, so it is a cultural trait.',complex:'It is a set of related traits that go together, so it is a cultural complex.'},'Culture');
 for(const [s,r,w] of MATERIAL){const c=choose(r,[w,'a cultural region'],MATERIAL.findIndex(x=>x[0]===s));put('culture',`${s}: is this material or nonmaterial culture? ${c.text}. Answer A, B or C.`,c.letter,tab('Culture',[['case',s]],['']),`It is ${r}.`,[r]);}
 /* landscape */
 ask('landscape',[['What is a cultural landscape?','the visible imprint of human activity and culture on the land',['the natural land before any people lived there','a painting of the countryside'],'A cultural landscape is the land as people have shaped it: farms, buildings, roads and signs that show their culture.'],
  ['Which geographer is closely associated with the idea of the cultural landscape?','Carl Sauer',['Thomas Malthus','Ernest Ravenstein'],'Carl Sauer, an American geographer, made the cultural landscape a central idea: culture is the agent that shapes the natural landscape.'],
  ['What is sequent occupancy?','the layering of successive cultures on the same place, each leaving its mark',['a group moving all at once to a new place','the order in which census data are collected'],'Sequent occupancy is when groups live in one place one after another, each leaving marks that layer on the landscape.'],
  ['What is a toponym?','a place name',['a type of building','a language family'],'A toponym is a place name. Studying toponyms can reveal who lived in a place and what they valued.'],
  ['Why do place names help geographers study culture?','they often record the languages, people, beliefs or events of a place\'s past',['they show exactly how many people live there','they always describe the local climate'],'Place names often keep traces of the past: the language of earlier peoples, saints, founders or events, like Los Angeles or Mississippi.'],
  ['What is vernacular architecture?','building styles that use local materials and traditions',['designs copied from skyscrapers in global cities','buildings made only for tourists'],'Vernacular architecture is the local, traditional way of building, using local materials and suited to local climate and customs.'],
  ['What is an ethnic neighborhood?','an area where people of a shared heritage have clustered, often keeping language, food and religious traditions',['a district that only tourists visit','an area with no cultural identity'],'An ethnic neighborhood forms where people of a shared heritage cluster, often keeping their language, foods and places of worship.'],
  ['Which feature of a landscape most directly shows religion?','a house of worship, such as a church, mosque, synagogue or temple',['the slope of a hill','the average rainfall'],'Churches, mosques, synagogues and temples are built to express belief, so they show religion directly on the landscape.'],
  ['In a fictional town, a mill became a market hall and later a museum. Which idea does this layering show?','sequent occupancy',['hierarchical diffusion','a formal region'],'One building used by successive users, mill then market then museum, shows layers of occupation over time: sequent occupancy.'],
  ['How can signs in several languages shape a landscape?','they can show which groups live in or visit an area',['signs are never part of culture','signs show the soil type'],'Signs in several languages show which language groups live in or visit an area, so they mark culture on the landscape.']],tab('Cultural landscape',[['made by people','buildings, fields, roads, signs'],['layers','sequent occupancy'],['names','toponyms']],['Examples']));
 sort('landscape',SCAPE.slice(0,4),'Is this a cultural or a physical feature of a landscape?',{cultural:'People built or shaped it, so it is a cultural feature.',physical:'It formed naturally, so it is a physical feature.'},'Landscape');
 /* patterns */
 ask('patterns',[['What is a formal cultural region?','an area where most people share one or more cultural traits, such as a language',['an area linked around a central node, like a newspaper\'s delivery area','an area defined only by people\'s feelings about it'],'A formal region shares one or more traits throughout, such as a common language. Areas around a node are functional regions.'],
  ['What is a functional region?','an area organized around a central node, linked by flows such as transport or communication',['an area where everyone shares the same trait','an area that exists only in people\'s feelings'],'A functional region is organized around a node, like a city or airport, and tied together by flows such as commuting or broadcasts.'],
  ['What is a vernacular (perceptual) region?','an area people think of as a region, based on shared feelings and identity',['an area with exact legal borders','an area served by one node'],'A vernacular, or perceptual, region exists in people\'s minds, based on shared feelings and identity, like the South in the United States.'],
  ['What is folk culture?','traditional practices of a small, fairly uniform group, often rural and passed on locally',['trends spread quickly across the world by media','practices that have disappeared completely'],'Folk culture is traditional practice in small, fairly uniform, often rural groups, passed on locally and changing slowly.'],
  ['What is popular culture?','trends shared by large, varied groups, spread widely and changing quickly',['traditions kept by one small village','customs that never change'],'Popular culture is shared by large, varied populations, spreads fast through media and changes quickly.'],
  ['Which of these is most likely folk culture?','a village\'s traditional harvest dance, taught by elders',['a viral video challenge','a global streaming series'],'A traditional dance taught by elders in one village is passed on locally and changes slowly, which marks folk culture.'],
  ['Which of these is most likely popular culture?','a music style that spreads worldwide through streaming',['a healing tradition learned from a grandparent','a ceremony held only in one valley'],'A music style spreading worldwide through streaming reaches large, varied audiences fast, which marks popular culture.'],
  ['What is ethnicity?','identity based on shared ancestry, language, customs or heritage',['a person\'s citizenship on a passport','the climate of a person\'s home region'],'Ethnicity is identity based on shared ancestry, language, customs or heritage. Citizenship is a legal status, not an ethnicity.'],
  ['What is neolocalism?','a renewed attention to local culture and identity, often as a reaction to globalization',['the spread of one culture everywhere','the study of place names'],'Neolocalism is a renewed interest in local culture and identity, such as local breweries or festivals, often as a reaction to globalization.']],tab('Cultural patterns',[['formal','shared trait'],['functional','linked to a node'],['vernacular','a felt region']],['Region']));
 sort('patterns',REGION,'Is this a formal, functional or vernacular region?',{formal:'People in the area share a trait or it is officially defined, so it is a formal region.',functional:'It is organized around a central node, so it is a functional region.',vernacular:'It exists in people\'s minds, so it is a vernacular region.'},'Region');
 /* diffusion */
 ask('diffusion',[['What is cultural diffusion?','the spread of a cultural trait, idea or innovation from its hearth to other places',['the loss of a trait when people stop using it','the way mountains form'],'Cultural diffusion is the spread of a cultural trait, idea or innovation from its hearth to other places.'],
  ['What is a cultural hearth?','the place where a cultural trait or innovation began',['the capital city of a country','any place that is warm in winter'],'A cultural hearth is the place where a trait or innovation began, from which it spread.'],
  ['What is distance decay?','the farther a place is from a hearth, the less likely it is to adopt the trait',['the idea that all places adopt a trait at once','a trait losing meaning once written down'],'Distance decay means contact and influence weaken with distance, so places far from a hearth are less likely to adopt a trait.'],
  ['What is relocation diffusion?','the spread of a trait as people carrying it move to a new place',['spread from person to person outward from a hearth, like a ripple','spread from large cities down to smaller towns'],'Relocation diffusion happens when people move and carry a trait with them to a new place, such as migrants bringing their foods.'],
  ['What is hierarchical diffusion?','a trait spreads through a ranking, often from large or powerful places or people to smaller ones',['a trait spreads evenly to every neighbor','a trait moves only with migrants'],'In hierarchical diffusion a trait spreads through a ranking, such as from big cities or powerful people to smaller places or groups.'],
  ['What is contagious diffusion?','a trait spreads from person to person nearby, like a ripple outward from its hearth',['a trait is carried by migrants to a distant place','a trait is changed to fit a new culture'],'Contagious diffusion spreads from person to person to nearby places, like a ripple. Being carried by migrants is relocation diffusion.'],
  ['What is stimulus diffusion?','an underlying idea spreads, but the trait is changed to fit the new culture',['the exact trait is copied without change','a trait is carried by migrants'],'Stimulus diffusion spreads the underlying idea, but the trait is changed to fit the new culture, like menus adjusted to local tastes.'],
  ['Which of these can act as a barrier to diffusion?','physical barriers such as mountains or oceans, and cultural taboos',['a shorter distance','a new highway'],'Mountains, oceans and deserts slow the spread of traits, and so can cultural taboos or laws. Short distances and highways help diffusion.']],tab('Diffusion',[['relocation','people move'],['expansion','idea spreads'],['kinds','contagious, hierarchical, stimulus']],['Types']));
 sort('diffusion',RELOC.slice(0,4),'Is this relocation diffusion or expansion diffusion?',{relocation:'People carried the trait to a new place, so it is relocation diffusion.',expansion:'The trait spread among people without a move of its carriers, so it is expansion diffusion.'},'Diffusion');
 sort('diffusion',KIND.slice(0,5),'Is this contagious, hierarchical or stimulus diffusion?',{contagious:'It spread outward person to person, nearest first: contagious diffusion.',hierarchical:'It moved down a ranking of influence: hierarchical diffusion.',stimulus:'The idea spread but the trait was new: stimulus diffusion.'},'Diffusion');
 /* historical */
 ask('historical',[['Which long-distance trade network linked East Asia with Europe and carried goods, ideas and religions?','the Silk Road',['the Panama Canal','the Pony Express'],'The Silk Road network linked East Asia with the Mediterranean, carrying silk, spices, ideas and religions such as Buddhism and Islam.'],
  ['What was the Columbian Exchange?','the transfer of crops, animals, people and diseases between the Eastern and Western Hemispheres after 1492',['a trade treaty signed in 1492 between two empires','the spread of the printing press across Europe'],'After 1492, crops, animals, people and diseases moved between the hemispheres. Historians call this the Columbian Exchange.'],
  ['Which crops from the Americas spread to Europe, Africa and Asia?','maize (corn) and potatoes',['wheat and barley','coffee and tea'],'Maize (corn) and potatoes came from the Americas and spread widely after 1492. Wheat and barley came from Southwest Asia.'],
  ['Which animal did Europeans bring to the Americas after 1492?','horses',['llamas','turkeys'],'Horses were brought by Europeans after 1492 and changed life for many peoples in the Americas. Llamas and turkeys were already there.'],
  ['What is colonialism?','one state establishing and keeping rule over another territory and its people',['two countries joining as equals','a trading partnership with no government control'],'Colonialism is one state taking and keeping control over another territory and its people, often settling it and using its resources.'],
  ['How did colonialism help spread languages such as Spanish, Portuguese, French and English?','colonial rulers used them in government, trade and schools, and settlers carried them abroad',['colonized peoples were never required to learn them','they spread only through the internet'],'Colonial rulers used their languages in government, trade and schools, and settlers carried them, so they spread worldwide.'],
  ['What lasting cultural result followed the forced migration of millions of enslaved Africans to the Americas?','African foodways, music and religious traditions became part of cultures in the Americas',['no African cultural influence reached the Americas','all African languages disappeared from Africa'],'Enslaved Africans brought foods, music and religious traditions with them, which shaped cultures across the Americas.'],
  ['Which spread from India toward East Asia along trade routes over many centuries?','Buddhism',['the potato','the telegraph'],'Buddhism began in northern India and spread over many centuries along trade routes to China, Korea and Japan.'],
  ['What did steamships, railways and the telegraph do in the 1800s?','they sped up the movement of people, goods and information, which sped diffusion',['they slowed diffusion by making travel more dangerous','they had no effect on diffusion'],'Steamships, railways and the telegraph made travel and messages much faster in the 1800s, so ideas and goods spread more quickly.'],
  ['What role did missionaries play in historical diffusion?','they carried religions, and often languages and schooling, to new places',['they only traveled inside their home countries','they built the Silk Road'],'Missionaries traveled to spread their faith, often bringing their language and schools too, so they drove the diffusion of religion.']],tab('Historical diffusion',[['trade','Silk Road'],['exchange','Columbian Exchange'],['empire','colonialism'],['technology','steamships, telegraph']],['Cause']));
 for(const [d,v] of [[1500,25],[2400,30],[900,20],[1800,24]]){const t=d/v;put('historical',`A fictional caravan travels ${v} kilometers a day along a trade route that is ${n(d)} kilometers long. How many days does the trip take?`,t,tab('A fictional caravan',[['distance',`${n(d)} km`],['speed',`${v} km per day`]]),`${n(d)} ÷ ${v} = ${pct(t)} days.`);}
 /* contemporary */
 ask('contemporary',[['What is globalization?','the growing connection of people, economies and cultures around the world',['the division of the world into isolated regions','the spread of one language by law'],'Globalization is the growing connection of people, economies and cultures worldwide through trade, travel and communication.'],
  ['What is time-space compression?','the shrinking of the effective time needed to travel or communicate between places, making the world feel smaller',['the physical shrinking of distances on Earth','the slowing of travel because of distance'],'Time-space compression means faster travel and communication make places feel closer. The real distance does not change.'],
  ['Which technologies did the most to produce time-space compression in recent decades?','the internet and mobile communication, along with air travel',['the printing press and the sailing ship','the horse-drawn cart'],'The internet, mobile phones and air travel cut the time to reach distant places, compressing time and space in recent decades.'],
  ['What is a transnational corporation?','a company that operates in many countries',['a company owned by a government','a company with only local customers'],'A transnational corporation operates in many countries, making or selling goods across borders.'],
  ['How do social media and streaming help diffuse popular culture?','a song or video can reach audiences in many countries almost at once',['they only reach people living near their creators','they spread culture only when people migrate'],'Social media and streaming let a song or video reach people in many countries almost at once, without anyone moving.'],
  ['Why is English often used as a lingua franca in global business and science?','it is widely learned as a second language, in part because of the history of British and U.S. influence',['it has the most native speakers in the world','every country requires it by law'],'English spread through British colonial rule and later U.S. influence in business and science, so many learn it as a second language.'],
  ['How do migrants help spread cuisines to new places?','they carry food traditions and often open businesses that introduce them to new customers',['they never share their food','they only eat in their hearth'],'Migrants bring their food traditions and often open restaurants and shops, introducing their cuisine to new customers.'],
  ['Which of these is a contemporary cause of diffusion?','mass media such as film and television',['sailing ships carrying spices','overland caravans'],'Film and television carry cultural traits worldwide today. Spice ships and caravans were historical causes of diffusion.'],
  ['What is the digital divide?','the gap between people who have good access to the internet and technology and those who do not',['the gap between two time zones','the difference between two languages'],'The digital divide is the gap between people with good access to the internet and technology and those without, within or between countries.'],
  ['Why do air transport and container shipping matter to globalization?','they move people and goods across the world quickly and cheaply',['they keep goods in their hearths','they limit movement to nearby countries'],'Planes and container ships move people and goods quickly and cheaply around the world, which ties economies and cultures together.']],tab('Contemporary diffusion',[['globalization','growing links'],['time-space compression','the world feels smaller'],['divide','unequal access']],['Idea']));
 for(const [a,b] of [[40,30],[25,20],[200,50],[60,12],[48,36]]){const r=(a-b)/a*100;put('contemporary',`A fictional journey took ${a} hours by one route and ${b} hours after a new rail line opened. By what percent did the travel time fall?`,r,tab('A fictional journey',[['before',`${a} hours`],['after',`${b} hours`]]),`(${a} - ${b}) ÷ ${a} × 100 = ${pct(r)}%.`);}
 for(const [u,t] of [[12,40],[21,60],[33,44]]){const r=u/t*100;put('contemporary',`In a fictional country of ${t} million people, ${u} million use the internet. What percent of the population is that?`,r,tab('A fictional country',[['population',`${t} million`],['internet users',`${u} million`]]),`${u} ÷ ${t} × 100 = ${pct(r)}%.`);}
 /* religion */
 ask('religion',[['What is a universalizing religion?','a religion that actively seeks new members across places and cultures',['a religion tied to one ethnic group and place','a religion with only one holy site'],'A universalizing religion seeks converts across cultures and places, such as Christianity, Islam and Buddhism.'],
  ['What is an ethnic religion?','a religion closely tied to a particular ethnic group or place, which generally does not seek converts',['a religion that sends missionaries worldwide','a religion with no beliefs'],'An ethnic religion is tied to one group or place and generally does not seek converts, such as Hinduism, Judaism or Shinto.'],
  ['Which three are the largest universalizing religions?','Christianity, Islam and Buddhism',['Hinduism, Judaism and Shinto','Christianity, Hinduism and Judaism'],'Christianity, Islam and Buddhism are the largest universalizing religions. Hinduism, Judaism and Shinto are ethnic religions.'],
  ['Where is the hearth of Islam?','the Arabian Peninsula',['northern India','Western Europe'],'Islam began in the Arabian Peninsula, in Mecca and Medina, in the 600s CE, then spread across Southwest Asia, North Africa and beyond.'],
  ['Where did Buddhism begin, according to the usual account?','northern India',['the Arabian Peninsula','West Africa'],'By the usual account, Buddhism began in northern India with Siddhartha Gautama, the Buddha, about 2,500 years ago.'],
  ['Where is the hearth of Christianity?','Southwest Asia',['East Asia','Central America'],'Christianity began in Southwest Asia, in the eastern Mediterranean region around Jerusalem, in the first century CE.'],
  ['What are the two main branches of Islam?','Sunni and Shi\'a',['Catholic and Protestant','Theravada and Mahayana'],'Sunni and Shi\'a are the two main branches of Islam. Catholic and Protestant are Christian, and Theravada and Mahayana are Buddhist.'],
  ['Which are three main branches of Christianity?','Roman Catholic, Protestant and Eastern Orthodox',['Theravada, Mahayana and Vajrayana','Sunni, Shi\'a and Orthodox'],'Roman Catholic, Protestant and Eastern Orthodox are the three main branches of Christianity. Sunni and Shi\'a are branches of Islam.'],
  ['Theravada, Mahayana and Vajrayana are branches of which religion?','Buddhism',['Hinduism','Islam'],'Theravada, Mahayana and Vajrayana are the main branches of Buddhism.'],
  ['How did universalizing religions mainly spread?','through missionaries, traders, migrants and rulers who adopted them',['only through the migration of an entire hearth population','they never spread at all'],'Universalizing religions spread through missionaries, traders and migrants, and when rulers adopted them, they spread to their lands.'],
  ['Why do ethnic religions diffuse mainly by relocation?','they do not usually seek converts, so they spread mostly as followers migrate',['they spread by contagious diffusion to all neighbors','followers may not leave home'],'Ethnic religions rarely seek converts, so they spread mostly when their followers move. That is relocation diffusion.'],
  ['By most estimates, which religion has the most followers worldwide?','Christianity',['Hinduism','Buddhism'],'By most estimates, such as Pew Research\'s, Christianity has the most followers, about 2.3 billion, followed by Islam.']],tab('Religion',[['universalizing','seeks converts'],['ethnic','tied to a people or place'],['branches','within a religion']],['Idea']));
 for(const [r,k] of FAITH.slice(0,5))put('religion',`${r} is usually classified as which kind of religion, universalizing or ethnic?`,k,tab('Religion',[['religion',r]],['']),`${r} is usually classified as ${k}.`);
 /* language */
 ask('language',[['What is a language family?','a group of languages that share a common ancestor in the distant past',['a group of languages spoken in one country','a language used by one family at home'],'A language family is a group of languages that descend from one common ancestor language, like Indo-European.'],
  ['Which sequence goes from the largest grouping to the smallest?','family, branch, group, language, dialect',['dialect, language, group, branch, family','branch, family, dialect, group, language'],'From largest to smallest: language family, branch, group, single language, then dialect within that language.'],
  ['What is a dialect?','a regional or social variety of a language with its own vocabulary, pronunciation or grammar',['a language with no speakers','a writing system'],'A dialect is a regional or social variety of one language, with its own words, accent or grammar, like American and British English.'],
  ['Which language family has the most speakers worldwide?','Indo-European',['Sino-Tibetan','Afro-Asiatic'],'Indo-European has the most native speakers of any language family, with languages like English, Spanish, Hindi and Russian.'],
  ['Spanish, French and Italian belong to which branch of Indo-European?','Romance',['Germanic','Indo-Iranian'],'Spanish, French and Italian come from Latin, the language of the Romans, so they form the Romance branch.'],
  ['English, German and Dutch belong to which branch of Indo-European?','Germanic',['Romance','Balto-Slavic'],'English, German and Dutch descend from a common Germanic ancestor, so they form the Germanic branch.'],
  ['Russian and Polish belong to which branch of Indo-European?','Balto-Slavic',['Romance','Germanic'],'Russian and Polish are Slavic languages, part of the Balto-Slavic branch along with languages such as Lithuanian.'],
  ['Hindi and Persian belong to which branch of Indo-European?','Indo-Iranian',['Romance','Balto-Slavic'],'Hindi and Persian (Farsi) are in the Indo-Iranian branch, the largest Indo-European branch by number of languages.'],
  ['Mandarin Chinese belongs to which language family?','Sino-Tibetan',['Indo-European','Austronesian'],'Mandarin Chinese belongs to the Sino-Tibetan family. Austronesian includes languages like Malay and Tagalog.'],
  ['Basque is usually classified as what kind of language?','a language isolate',['a dialect of Spanish','a pidgin'],'Basque is not related to any other known language, so linguists call it a language isolate. It is not a dialect of Spanish.'],
  ['What is a lingua franca?','a language used for communication between people whose first languages differ',['a language that has died out','the oldest language in a family'],'A lingua franca is a shared language people use to communicate when their first languages differ, like English or Swahili in many settings.'],
  ['What is a pidgin?','a simplified language that develops so groups with no common language can communicate',['the official language of a country','a language a child is born speaking'],'A pidgin is a simplified language that grows up when groups with no common language need to talk, often for trade. No one learns it as a first language.'],
  ['What is a creole in the traditional pidgin-to-creole model?','a language that develops from a pidgin and becomes a community\'s first language',['a language with no grammar','an ancient written language'],'In the traditional model, a pidgin becomes a creole when children learn it as their first language and it gains a full grammar.'],
  ['What do linguists use to reconstruct ancient languages?','similar words and sounds (cognates) across related languages',['the spelling of names on modern maps','the number of speakers today'],'Cognates are words with a shared origin, like night, Nacht and noche. Comparing them helps linguists reconstruct ancestor languages.']],tab('Language',[['family','shared distant ancestor'],['branch','closer relatives'],['dialect','regional variety']],['Idea']),1);
 /* effects */
 ask('effects',[['What is acculturation?','adopting some traits of another culture while keeping one\'s own',['giving up one\'s culture entirely to match the dominant one','avoiding all contact with other cultures'],'In acculturation a group adopts some traits of another culture, often the dominant one, while still keeping its own.'],
  ['What is assimilation?','adopting the dominant culture so fully that one\'s distinctive traits fade',['mixing two religions into a new one','keeping every original trait unchanged'],'In assimilation people take on the dominant culture so fully that their original distinctive traits fade away.'],
  ['In cultural geography, what is syncretism?','the blending of elements from different cultures or religions into a new form',['replacing one culture by force','the spread of a trait by migrants'],'Syncretism blends elements of different cultures or religions into something new, such as Vodou combining African and Catholic traditions.'],
  ['What is multiculturalism?','a society in which several cultures coexist and each keeps its identity',['a policy that all people must adopt one culture','a language spoken by many countries'],'Multiculturalism is when several cultures live side by side in one society and each keeps its own identity.'],
  ['What is cultural convergence?','cultures becoming more alike as they interact',['cultures becoming more different','cultures ending all contact'],'Cultural convergence is when cultures become more alike through contact, such as through trade, media and travel.'],
  ['What is cultural divergence?','cultures becoming more different, often as groups resist or avoid outside influences',['cultures becoming more alike','cultures swapping their names'],'Cultural divergence is when cultures become more different, often as groups separate or resist outside influence.'],
  ['What is glocalization?','adapting a global product or idea to local tastes and customs',['the end of all local culture','the spread of a product with no changes'],'Glocalization is adapting a global product or idea to local tastes, such as a fast-food chain offering local dishes.'],
  ['Why are many small languages endangered?','speakers often shift to a dominant language used in schools, work and media',['small languages have more speakers than large ones','children cannot learn a small language'],'When schools, jobs and media use a dominant language, younger people often switch to it, and fewer children learn the small language.'],
  ['What do critics of globalization worry about?','that local traditions may be displaced by a few dominant global trends',['that all trade will end','that people will stop using phones'],'Critics worry that a few global brands and trends may crowd out local traditions, making cultures more alike.'],
  ['Which is one way communities respond to the loss of a threatened language?','teaching it in schools and recording it',['banning travel','abandoning all traditions'],'Communities keep languages alive by teaching them in schools and recording speakers, stories and songs.']],tab('Effects of diffusion',[['acculturation','adopt some, keep your own'],['assimilation','adopt the dominant culture'],['syncretism','blend'],['multiculturalism','many coexist']],['Means']),2);
 sort('effects',EFFECT,'Which term fits best: acculturation, assimilation, syncretism or multiculturalism?',{acculturation:'The people adopt some new traits and keep their own: acculturation.',assimilation:'The distinctive traits fade into the dominant culture: assimilation.',syncretism:'Elements are blended into a new form: syncretism.',multiculturalism:'Several cultures coexist and each keeps its identity: multiculturalism.'},'Effects');
}};
